export const HOW_DE = {
  lead: (n: number) => `Du startest mit einem kurzen Fragebogen, ohne Konto und ohne Upload. Wir vergleichen deine Interessen und einige Schulfächer mit ${n} Studienfeldern. Eigene Daten kannst du freiwillig für einen zweiten Blick ergänzen.`,
  questionnaireTitle: '1. Den Fragebogen ausfüllen',
  questionnaireIntro: 'Im Fragebogen schätzt du ein, welche Tätigkeiten dir gefallen und welche Schulfächer du gern hast. Dazu kommt grob deine letzte Mathematiknote. Du brauchst dafür keinen Suchverlauf und keine verbundenen Konten.',
  questionnaireParts: [
    ['Schulfächer und Mathematiknote', 'Du gibst an, wie gern du deine 14 Schulfächer hast; Fächer, die du nicht hast, lässt du leer. Deine letzte Mathematiknote gibst du grob an. Sie steht bei Fächern mit viel Mathematik als Hinweis zur Machbarkeit und verändert die Rangliste nicht.'],
    ['Tätigkeiten', '45 Fragen zu Tätigkeiten in 15 Bereichen, die es als Schulfach nicht gibt, etwa Technik, Medizin, Recht, Beraten oder Führen, in zufälliger Reihenfolge. 12 Bereiche stammen aus dem frei verfügbaren CABIN-NET (Chu et al., 2025), drei sind eigene Fragen. Die sechs Interessentypen nach Holland werden aus Fächern und Tätigkeiten zusammengefasst. Für ein Resultat brauchst du in jedem Bereich mindestens zwei Antworten und mindestens zehn Fächer.'],
    ['Was dir wichtig ist', 'Im Resultat wählst du aus, was dir im Beruf wichtig ist, etwa Sicherheit oder Kreativität, und filterst damit die Fächer. Die Passung ändert sich dadurch nicht.'],
  ],
  matchTitle: '2. Passende Studienfelder finden',
  matchIntro: 'Wir vergleichen dein Profil mit den Profilen der Studienfelder. Die Rangliste beruht nur auf der Interessenpassung: wie ähnlich die Form deines Profils aus Interessenbereichen und Schulfächern dem des Fachs ist. Die Profile der Fächer stammen aus den Wissensanforderungen der Berufe, zu denen sie führen (O*NET). Fächer, die weniger als 5 Punkte auseinanderliegen, zeigen wir als Gruppe, weil so kleine Unterschiede keine echte Rangfolge sind.',
  matchMeaning: 'Die Passungswerte helfen dir, Fächer miteinander zu vergleichen. Sie sind keine Wahrscheinlichkeit für einen Studienerfolg. Wenn dein Interessenprofil wenig Unterschiede zeigt oder Fächer nahe beieinanderliegen, weisen wir darauf hin.',
  resultTitle: '3. Dein Resultat und die Studiengänge anschauen',
  resultIntro: 'Passende Fächer kannst du dir gratis ansehen. Dein bestes Fach und dein bester Studiengang gehören zum kostenpflichtigen Report. Dort findest du passende Studiengänge an konkreten Hochschulen aus den abgedeckten Ländern und kannst einzelne Studiengänge freiwillig mit KI mit deinem Profil vergleichen.',
  dataTitle: 'Optional: eigene Daten ergänzen',
  dataIntro: 'Mit dem Modus «Mit deinen Daten» kannst du zum Beispiel einen YouTube-, Instagram- oder TikTok-Export ergänzen. Wenn dein Interessenfragebogen auswertbar ist, bleibt die Rangliste allein beim Fragebogen; die Daten erscheinen als Beispiele und Themen bei den Fächern und helfen beim Sortieren einzelner Studiengänge. Ohne auswertbaren Interessenfragebogen ist die Datenanalyse ein Experiment mit geringer Sicherheit.',
  dataDetails: 'Wie die freiwillige Datenanalyse funktioniert',
  limitsTitle: 'Was das Resultat nicht kann',
  limits: [
    'Deine Antworten sind Selbsteinschätzungen. Der Fragebogen prüft weder deine Fähigkeiten noch die Zulassung zu einem Studiengang. Wie gut du in einem Studium abschneidest, sagen deine Schulnoten deutlich besser voraus als deine Interessen.',
    'Ein ähnliches Interessenprofil allein sagt Zufriedenheit und Erfolg im Studium nicht zuverlässig voraus. Das Resultat hilft dir, Möglichkeiten einzugrenzen.',
    'Falls du Daten ergänzt: Geteilte Konten, Autoplay und vorübergehende Interessen können das Bild verzerren. Inhalte in anderen Sprachen als Deutsch, Englisch, Französisch, Italienisch und Spanisch werden nur teilweise erkannt.',
    'Sprich mit Studierenden und einer Studienberatung, schau dir Studienpläne an und geh an einen Infotag, bevor du dich entscheidest.',
  ],
}

